const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function project(x,y,z){let dx=x-state.x,dz=z-state.z,c=Math.cos(state.yaw),s=Math.sin(state.yaw),xx=dx*c-dz*s,zz=dx*s+dz*c;if(zz<.15)return null;let focal=Math.min(w,h)*.82,scale=focal/zz;return {x:w*.5+xx*scale,y:h*.51-(y-1.65-state.pitch)*scale,scale,z:zz}}
