function line3(a,b,color,width=1){let p=project(...a),q=project(...b);if(!p||!q)return;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function box(x,y,z,wx,wy,wz,color,edge='rgba(117,211,206,.3)'){poly([[x-wx/2,y,z],[x+wx/2,y,z],[x+wx/2,y+wy,z],[x-wx/2,y+wy,z]],color,edge);poly([[x-wx/2,y,z],[x-wx/2,y,z+wz],[x-wx/2,y+wy,z+wz],[x-wx/2,y+wy,z]],shade(color,.62),edge);poly([[x+wx/2,y,z],[x+wx/2,y,z+wz],[x+wx/2,y+wy,z+wz],[x+wx/2,y+wy,z]],shade(color,.82),edge);poly([[x-wx/2,y+wy,z],[x+wx/2,y+wy,z],[x+wx/2,y+wy,z+wz],[x-wx/2,y+wy,z+wz]],shade(color,1.3),edge)}
function shade(hex,k){let m=hex.match(/\w\w/g);if(!m)return hex;return '#'+m.slice(0,3).map(v=>Math.max(0,Math.min(255,parseInt(v,16)*k|0)).toString(16).padStart(2,'0')).join('')}
