// distant planet visible through panoramic windows
let cx=w*.72,cy=h*.39,rad=Math.min(w,h)*.15;let pg=ctx.createRadialGradient(cx-rad*.35,cy-rad*.4,rad*.05,cx,cy,rad);let pc=state.room===10?'#cc8874':state.selectedPlanet===1?'#d8aa6d':state.selectedPlanet===2?'#71ad92':'#8c718f';pg.addColorStop(0,'#f1d0a6');pg.addColorStop(.45,pc);pg.addColorStop(.82,shade(pc,.55));pg.addColorStop(1,'#16242e');ctx.save();ctx.globalAlpha=.88;ctx.shadowColor=pc;ctx.shadowBlur=30;ctx.beginPath();ctx.arc(cx,cy,rad,0,7);ctx.fillStyle=pg;ctx.fill();ctx.restore();ctx.save();ctx.beginPath();ctx.arc(cx,cy,rad,0,7);ctx.clip();ctx.globalAlpha=.16;for(let i=0;i<8;i++){ctx.fillStyle=i%2?'#d9b685':'#5d7983';ctx.beginPath();ctx.ellipse(cx+Math.sin(i*12)*rad*.5,cy+(i-4)*rad*.25,rad*(.2+i%3*.1),rad*.09,i*.6,0,7);ctx.fill()}ctx.restore();let halo=ctx.createRadialGradient(cx,cy,rad*.84,cx,cy,rad*1.25);halo.addColorStop(0,'rgba(123,218,216,.2)');halo.addColorStop(1,'transparent');ctx.fillStyle=halo;ctx.beginPath();ctx.arc(cx,cy,rad*1.25,0,7);ctx.fill()}
