poly([[-6,0,0],[6,0,0],[6,0,far],[-6,0,far]],'rgba(29,48,54,.24)','rgba(153,195,193,.12)');poly([[-6,5.2,0],[6,5.2,0],[6,5.2,far],[-6,5.2,far]],'rgba(15,27,34,.28)','rgba(153,195,193,.08)');poly([[-6,0,0],[-6,5.2,0],[-6,5.2,far],[-6,0,far],'rgba(24,39,45,.8)','rgba(150,185,185,.15)');poly([[6,0,0],[6,5.2,0],[6,5.2,far],[6,0,far]],'rgba(25,41,46,.78)','rgba(150,185,185,.15)');
// window frame, vertical mullions and luminous sill
