// structural ribs and ceiling lights
for(let z=1;z<14;z+=3.2){line3([-5.8,5.08,z],[5.8,5.08,z],'rgba(143,181,182,.18)',2);line3([-5.8,.12,z],[5.8,.12,z],'rgba(98,145,148,.2)',2);box(-5.65,4.92,z,.12,.13,1.8,'#385257','rgba(112,225,209,.35)');box(5.65,4.92,z,.12,.13,1.8,'#385257','rgba(112,225,209,.35)')}
// floor light strips and perspective deck seams
line3([-5.7,.05,0],[-5.7,.05,14],accent,2);line3([5.7,.05,0],[5.7,.05,14],accent,2);for(let z=1;z<14;z+=1.3)line3([-5.7,.04,z],[5.7,.04,z],'rgba(105,158,159,.14)',1);for(let x=-5;x<=5;x+=1.25)line3([x,.04,0],[x,.04,14],'rgba(105,158,159,.1)',1);
// side wall panels
for(let side of [-1,1])for(let z=1;z<13;z+=2.4){box(side*5.82,.4,z,.18,2.4,1.8,'#17272d','rgba(104,158,161,.28)');box(side*5.7,2.15,z,.14,.08,1.6,shade(accent,.68),'rgba(112,225,209,.32)')}
// captain's forward console and station clusters
for(let i=0;i<4;i++){let x=(i-1.5)*2.1;box(x,.15,8.4,1.65,1.05,1.05,i===1?'#28474a':'#1d3339','rgba(126,213,204,.42)');poly([[x-.72,1.2,8.7],[x+.72,1.2,8.7],[x+.72,2.12,8.7],[x-.72,2.12,8.7]],'rgba(52,119,119,.75)',accent);for(let k=0;k<4;k++)line3([x-.54+k*.34,1.35,8.66],[x-.54+k*.34,1.95,8.66],'rgba(133,237,210,.62)',1);line3([x-.65,2.2,8.65],[x+.65,2.2,8.65],accent,1)}
// captain chair in foreground
box(0,.15,4.1,1.3,.8,.9,'#273b3e','rgba(202,180,136,.5)');box(0,.9,4.35,1.35,1.35,.35,'#34494b','rgba(197,175,132,.48)');
}

