}
function drawPerson(x,z,index){let bob=Math.sin(time*2.7+index*2)*.035,skin=['#d3a68a','#e1b695','#9d735d','#c58f80'][index%4],suit=['#6c9392','#8575aa','#967350','#557c90'][index%4];let p=project(x,0,z);if(!p)return;let scale=p.scale,hip=project(x,.82+bob,z),head=project(x,1.55+bob,z),shoulder=project(x,.53+bob,z);if(!hip||!head||!shoulder)return;let width=scale*.28,height=scale*.24;ctx.strokeStyle='#263a3f';ctx.lineWidth=Math.max(2,scale*.075);ctx.beginPath();ctx.moveTo(hip.x-width*.35,hip.y);ctx.lineTo(p.x-width*.42,p.y);ctx.moveTo(hip.x+width*.35,hip.y);ctx.lineTo(p.x+width*.42,p.y);ctx.stroke();ctx.fillStyle=suit;ctx.beginPath();ctx.moveTo(shoulder.x-width*.52,shoulder.y);ctx.lineTo(shoulder.x+width*.52,shoulder.y);ctx.lineTo(hip.x+width*.4,hip.y);ctx.lineTo(hip.x-width*.4,hip.y);ctx.closePath();ctx.fill();ctx.strokeStyle=shade(suit,.7);ctx.lineWidth=Math.max(1,scale*.025);ctx.stroke();ctx.fillStyle=skin;ctx.beginPath();ctx.arc(head.x,head.y,Math.max(2,scale*.105),0,7);ctx.fill();ctx.fillStyle='#d5cf9f';ctx.fillRect(shoulder.x-width*.38,shoulder.y+scale*.12,Math.max(2,scale*.07),Math.max(2,scale*.14));let armSwing=Math.sin(time*2.3+index)*scale*.04;ctx.strokeStyle=suit;ctx.lineWidth=Math.max(2,scale*.1);ctx.beginPath();ctx.moveTo(shoulder.x-width*.4,shoulder.y+scale*.05);ctx.lineTo(shoulder.x-width*.58,shoulder.y+scale*.48+armSwing);ctx.moveTo(shoulder.x+width*.4,shoulder.y+scale*.05);ctx.lineTo(shoulder.x+width*.58,shoulder.y+scale*.48-armSwing);ctx.stroke()}
function drawRoomProps(){let n=state.room,accent=rooms[n].color;
if(n===0){for(let i=0;i<5;i++){drawPerson(-3.3+i*1.6,7.15+(i%2)*.6,i);}}
else {box(-2.2,.15,7.5,2.4,1.4,1.2,'#26393b','rgba(124,198,193,.42)');box(2.2,.15,7.7,2.4,1.5,1.1,'#21363b','rgba(124,198,193,.4)');for(let i=0;i<5;i++){let px=-3.3+(i%3)*3.1,pz=5.1+Math.floor(i/3)*3.1;box(px,.15,pz,1.5,1.15,.85,'#22393d','rgba(117,203,197,.45)');poly([[px-.63,1.32,pz+.44],[px+.63,1.32,pz+.44],[px+.63,1.95,pz+.44],[px-.63,1.95,pz+.44]],'rgba(47,108,112,.82)',accent);for(let b=0;b<3;b++)line3([px-.45+b*.35,1.45,pz+.41],[px-.45+b*.35,1.78,pz+.41],'rgba(137,231,211,.55)',1);if(i<rooms[n].people)drawPerson(px+(i%2?-.4:.4),pz-.72,i+n)}}
