let hx=4.2,hz=3.1;box(hx,.15,hz,1.35,.85,.85,'#263d42','rgba(124,198,193,.4)');let hp=project(hx,2.18,hz);if(hp){ctx.save();ctx.translate(hp.x,hp.y);ctx.rotate(time*.12);ctx.strokeStyle=accent;ctx.globalAlpha=.72;ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,0,Math.max(5,hp.scale*.72),Math.max(3,hp.scale*.26),0,0,7);ctx.stroke();ctx.rotate(-time*.24);ctx.strokeStyle='#91ddd0';ctx.beginPath();ctx.ellipse(0,0,Math.max(4,hp.scale*.48),Math.max(2,hp.scale*.18),0,0,7);ctx.stroke();ctx.fillStyle='rgba(102,218,203,.12)';ctx.fillRect(-hp.scale*.6,-hp.scale*.35,hp.scale*1.2,hp.scale*.7);for(let i=0;i<4;i++){ctx.fillStyle=`rgba(157,238,216,${.35+.3*Math.sin(time*2+i)})`;ctx.fillRect(-hp.scale*.42,-hp.scale*.2+i*hp.scale*.1,hp.scale*(.3+(i%2)*.24),Math.max(1,hp.scale*.018))}ctx.restore()}
// floating light motes and tiny deck status lamps
for(let i=0;i<20;i++){let x=Math.sin(time*.4+i*8)*5,z=1+(i*1.57)%12;circle3(x,1.5+Math.sin(time+i)*.3,z, .018,i%3===0?accent:'rgba(179,233,222,.55)')}
}
function render(){let dt=Math.min(.05,(performance.now()-last)/1000);last=performance.now();time+=dt;state.clock+=dt;drawSpace();roomShell();drawRoomProps();requestAnimationFrame(render)}

