function closeModal(){let wrap=$('#modalWrap');wrap.classList.remove('open');wrap.setAttribute('aria-hidden','true')}
function act(action){if(action==='travel'){if(state.selectedPlanet===0&&!state.travelled){state.travelled=true;state.fuel=Math.max(0,state.fuel-5);notify('ROTA DEFINIDA · ANOMALIA A 0,4 UA')}else if(state.fuel<12){notify('COMBUSTÍVEL INSUFICIENTE · REPONHA NO DEPÓSITO');return}else{state.fuel-=12;state.travelled=true;state.power=Math.max(20,state.power-3);notify('SALTO CONCLUÍDO · ORBITA DE '+planets[state.selectedPlanet].name.toUpperCase())}updateUI();save();renderMapInfo()}
if(action==='mission'){if(!state.mission){state.mission=1;state.morale=Math.min(100,state.morale+2);updateUI();save();notify('MISSÃO ACEITA · DEFINA UM DESTINO NO MAPA');openModal('map')}else{closeModal();if(state.room!==10)changeRoom(10);else dispatchExpedition()}}
if(action==='rest'){state.morale=Math.min(100,state.morale+5);notify('TURNO DE DESCANSO ORGANIZADO · MORAL +5');updateUI();save()}
if(action==='resupply'){if(state.credits<350){notify('FUNDOS INSUFICIENTES');return}state.credits-=350;state.supplies=Math.min(100,state.supplies+18);notify('SUPRIMENTOS RECEBIDOS · +18%');updateUI();save()}
