if(action==='resume')closeModal();if(action==='reset'){if(confirm('Reiniciar a campanha? O progresso salvo será apagado.')){localStorage.removeItem('orbit-save');location.reload()}}
if(action==='room-visit'){let r=rooms[state.room];if(state.expedition){state.expedition=false;state.credits+=1200;state.supplies=Math.max(0,state.supplies-5);state.morale=Math.min(100,state.morale+4);state.mission=0;state.travelled=false;state.fuel=Math.min(100,state.fuel+4);state.room=10;state.x=0;state.z=2;updateUI();save();notify('EXPEDIÇÃO CONCLUÍDA · ₡ 1.200 + DESCOBERTA CIENTÍFICA');return}if(state.room===10){dispatchExpedition();return}if(state.room===0){state.seated=!state.seated;notify(state.seated?'CADEIRA DO CAPITÃO · SISTEMAS DE COMANDO ATIVOS':'COMANDO ATIVO · BOA VIAGEM, CAPITÃ');return}state.credits+=50;state.morale=Math.min(100,state.morale+1);if(state.room===1)state.power=Math.min(100,state.power+3);if(state.room===2)state.power=Math.min(100,state.power+1);if(state.room===3)state.supplies=Math.min(100,state.supplies+2);if(state.room===5)state.mission=state.mission?state.mission:0;notify('TURNO REGISTRADO · '+r.short.toUpperCase()+' · +₡ 50');updateUI();save()}}
function dispatchExpedition(){if(!state.travelled){notify('DEFINA UM DESTINO NO MAPA ESTELAR PRIMEIRO');openModal('map');return}if(state.fuel<8||state.supplies<8){notify('RECURSOS INSUFICIENTES PARA A LANÇADEIRA');return}state.expedition=true;state.fuel-=4;state.supplies-=3;state.room=10;state.x=0;state.z=1.5;state.yaw=0;updateUI();notify('LANÇADEIRA DESACOPLADA · EXPEDIÇÃO INICIADA');save()}
function doInteract(){if(state.expedition){act('room-visit');return}act('room-visit')}
function handleClick(e){let t=e.target.closest('[data-panel],[data-room],[data-planet],[data-action],[data-upgrade]');if(!t)return;if(t.dataset.panel){let p=t.dataset.panel;if(p==='bridge'){changeRoom(0);return}openModal(p);return}if(t.dataset.room!==undefined){changeRoom(+t.dataset.room);return}if(t.dataset.planet!==undefined){state.selectedPlanet=+t.dataset.planet;renderMapInfo();return}if(t.dataset.action){act(t.dataset.action);return}if(t.dataset.upgrade){let cost=+t.dataset.cost;if(state.credits<cost){notify('FUNDOS INSUFICIENTES');return}state.credits-=cost;if(t.dataset.upgrade==='drive')state.fuel=Math.min(100,state.fuel+5);if(t.dataset.upgrade==='garden')state.supplies=Math.min(100,state.supplies+10);if(t.dataset.upgrade==='shields')state.morale=Math.min(100,state.morale+1);updateUI();save();notify('MELHORIA INSTALADA · SISTEMA ATUALIZADO');t.disabled=true;t.textContent='INSTALADO';}}
