let keys={},pointerLocked=false,drag=false,lastMouseX=0,lastMouseY=0;window.addEventListener('keydown',e=>{if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='e'&&!e.repeat){doInteract()}if(e.key==='Escape'){closeModal();if(document.pointerLockElement)document.exitPointerLock()}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
