function movement(dt){if($('#modalWrap').classList.contains('open'))return;let f=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),side=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),speed=state.expedition?2.3:3.1;if(f||side){let l=Math.hypot(f,side);f/=l;side/=l;state.x+=((Math.sin(state.yaw)*f)+(Math.cos(state.yaw)*side))*speed*dt;state.z+=((Math.cos(state.yaw)*f)-(Math.sin(state.yaw)*side))*speed*dt;state.x=clamp(state.x,-4.8,4.8);state.z=clamp(state.z,.8,12.5)}}
