import { createRequire } from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json'); const {chromium}=require('playwright');
const b=await chromium.launch({headless:true}); const p=await b.newPage({viewport:{width:390,height:844}}); const errors=[];p.on('pageerror',e=>errors.push(e.message));
await p.goto('http://localhost:3000'); await p.evaluate(()=>localStorage.clear()); await p.reload();
for(const sel of ['.view-top','.location h1','.condition','.help','.view-bottom','.hud-label','.dock'])console.log(sel,await p.locator(sel).boundingBox());
await p.locator('#helpClose').click();
await p.locator('[data-panel="departments"]').click(); console.log('departments',await p.locator('.department').count()); await p.locator('[data-room="3"]').click(); console.log('room',await p.locator('#roomTitle').textContent());
await p.locator('[data-panel="crew"]').click();await p.locator('[data-action="rest"]').click();console.log('morale',await p.locator('#morale').textContent());
await p.locator('.dock-btn[data-panel="missions"]').click();await p.locator('[data-action="mission"]').click();console.log('map open',await p.locator('#modalWrap').getAttribute('class'));
await p.locator('[data-planet="1"]').click();await p.locator('[data-action="travel"]').click();console.log('fuel after travel',await p.locator('#resFuel').textContent());
await p.reload();console.log('reload status',await p.locator('#roomTitle').textContent(),await p.locator('#resFuel').textContent());
await p.locator('.dock-btn[data-panel="missions"]').click(); await p.locator('[data-action="mission"]').click(); await p.keyboard.press('e');console.log('launch state',await p.locator('#objective').textContent());await p.keyboard.press('e');console.log('completion',await p.locator('#credits').textContent(),await p.locator('#missionTitle').textContent());
console.log('errors',errors,'save',await p.evaluate(()=>localStorage.getItem('orbit-save'))); await p.reload();console.log('reloaded',await p.locator('#roomTitle').textContent(),await p.locator('#credits').textContent()); await b.close();
