 :root{--bg:#071018;--panel:#0b171f;--line:rgba(182,214,220,.12);--text:#e9f1f0;--muted:#83979c;--teal:#70e1d1;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Manrope',sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#050b10;color:var(--text);font-family:var(--sans);overflow:hidden}button{font:inherit;color:inherit}#game{height:100dvh;min-height:600px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 38% 38%,#14232d,#080f15 70%)}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.grain{position:absolute;inset:0;pointer-events:none;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.23'/%3E%3C/svg%3E")}.topbar{height:74px;position:absolute;top:0;left:0;right:0;z-index:5;display:flex;align-items:center;padding:0 31px;background:linear-gradient(180deg,rgba(5,12,17,.96),rgba(6,14,19,.78));border-bottom:1px solid var(--line);backdrop-filter:blur(16px)}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none;width:260px}.brand>span:last-child{display:flex;flex-direction:column;line-height:1}.brand b{font:800 16px var(--display);letter-spacing:.2em}.brand small{font:9px var(--mono);letter-spacing:.19em;color:#809498;margin-top:5px}.brand-mark{width:31px;height:31px;border:1px solid rgba(112,225,209,.65);border-radius:50%;display:grid;place-items:center;position:relative}.brand-mark:before{content:'';position:absolute;width:18px;height:18px;border:1px solid var(--teal);border-radius:50%}.brand-mark i{position:absolute;width:4px;height:4px;background:var(--teal);border-radius:50%}.brand-mark i:nth-child(1){transform:translate(8px,-5px)}.brand-mark i:nth-child(2){transform:translate(-7px,5px);opacity:.7}.bran