const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
(async () => {
  const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
  process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
  const browser = await chromium.launch(config.browser.launchOptions);
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto('http://localhost:3000');
    await page.evaluate(() => localStorage.removeItem('orbit-save'));
    await page.reload();
    await page.locator('[data-panel="missions"]').click();
    await page.locator('[data-action="mission"]').click();
    await page.locator('[data-action="travel"]').click();
    await page.locator('[data-panel="departments"]').click();
    await page.locator('[data-room="10"]').click();
    await page.keyboard.press('e');
    let saved = await page.evaluate(() => JSON.parse(localStorage.getItem('orbit-save')));
    if (!saved.expedition || !saved.travelled) throw new Error('Expedition did not launch/persist: ' + JSON.stringify(saved));
    const before = saved.credits;
    await page.reload();
    if (!(await page.locator('#interaction').isVisible())) throw new Error('Return button missing after reload');
    await page.locator('#interaction').click();
    saved = await page.evaluate(() => JSON.parse(localStorage.getItem('orbit-save')));
    if (saved.expedition || saved.travelled || saved.mission !== 0 || saved.credits !== before + 1200) throw new Error('Button return reward/state incorrect: ' + JSON.stringify(saved));
    const afterButton = saved.credits;
    await page.evaluate(() => localStorage.setItem('orbit-save', JSON.stringify({ ...JSON.parse(localStorage.getItem('orbit-save')), travelled: true, mission: 1, room: 10, credits: 8450, fuel: 74, supplies: 68, expedition: false })));
    await page.reload();
    await page.keyboard.press('e');
    saved = await page.evaluate(() => JSON.parse(localStorage.getItem('orbit-save')));
    if (!saved.expedition) throw new Error('Keyboard E did not launch expedition');
    await page.keyboard.press('e');
    saved = await page.evaluate(() => JSON.parse(localStorage.getItem('orbit-save')));
    if (saved.expedition || saved.credits !== 9650 || saved.mission !== 0) throw new Error('Keyboard E completion incorrect: ' + JSON.stringify(saved));
    if (errors.length) throw new Error('Page errors: ' + errors.join('; '));
    console.log(JSON.stringify({ buttonReturnCredits: afterButton, keyboardReturnCredits: saved.credits, final: saved }, null, 2));
  } finally { await browser.close(); }
})().catch(e => { console.error(e); process.exit(1); });

